body:
{
  "pains": [
    {
      "id": "pain:nuclear-verdicts",
      "statement": "One crash we can't prove wasn't our fault can bury the company, and our insurance keeps going up even when we don't crash.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Insurance claims and premiums keep climbing, and plaintiff lawyers go after carriers with deep pockets.",
        "operational": "Without video, every crash comes down to the driver's word against the plaintiff's, and the carrier either settles or takes a jury verdict.",
        "personal": "The fleet or safety leader owns the claims number, has to explain it at renewal, and knows one bad verdict can end the business."
      },
      "workflow": "After a crash the safety manager pulls whatever evidence exists, sends it to the insurer and defense counsel, and waits for the claim or lawsuit. At renewal the fleet manager defends the loss history to the insurer.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "paying",
        "what": "Carriers pay for dual-facing cameras and hire safety staff to review camera events. A fleet buyer posted in January 2026 that its claims were at an all-time high before it acted, and a defense firm won dismissal on dash cam video alone.",
        "cites": ["src:6", "src:9", "src:15"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Claims spike across the fleet", "cites": ["src:6"] },
        { "event": "A crash lawsuit where liability is disputed", "cites": ["src:15"] },
        { "event": "Insurance renewal with a higher cost per mile", "cites": ["src:10"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "At the beginning of November, our insurance claims were at an all-time high across the fleet.", "cites": ["src:6"] }
          ],
          "costs_them": "Insurance at 10.6 cents a mile and rising, plus settlements and verdicts that dwarf it.",
          "fears": "A single nuclear verdict that the policy doesn't cover.",
          "dream_outcome": "Every disputed crash has video, and claims fall enough to show up at renewal."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Review inward and outward-facing camera events to identify coaching opportunities and recognize safe driving behaviors.", "cites": ["src:9"] }
          ],
          "costs_them": "Time spent piecing together what happened after every incident.",
          "fears": "Being the one who couldn't produce evidence when the case went to trial.",
          "dream_outcome": "Pull the clip, prove the driver stayed in their lane, close the case."
        }
      },
      "relief": {
        "line": "Video wins the case. The footage shows what happened, and the claim gets dismissed instead of settled.",
        "says": [
          { "role": "economic_buyer", "verbatim": "Inward and outward cameras are probably the best things that we've implemented", "cites": ["src:4"] }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Insurable again. The carrier's loss history becomes something it can show off at renewal, not hide.",
        "says": [],
        "gap": "Searched trade press, Trustpilot and forums for a buyer describing lower premiums a year on; found none in a buyer's own words. G2, Capterra and TrustRadius were blocked."
      },
      "segments": ["seg:trucking", "seg:construction"],
      "feature_ref": "feat:cameras",
      "cites": ["src:5", "src:6", "src:9", "src:10", "src:15"]
    },
    {
      "id": "pain:camera-rollout-drives-drivers-off",
      "statement": "We need the cameras for liability, but turn one toward the driver and good drivers start talking about quitting.",
      "element": "b2b:ease_of_doing_business:cultural_fit",
      "shape": {
        "surface": "Drivers push back hard when driver-facing cameras get announced.",
        "operational": "With turnover at 44%, losing drivers over a camera rollout costs more than the camera saves, so some fleets switch the inward lens off.",
        "personal": "The fleet leader has to sell the rollout to drivers who don't trust it, and wears the blame if drivers walk."
      },
      "workflow": "During a camera install the operations or safety manager briefs drivers, answers whether the camera records audio or watches all the time, and then handles the drivers who refuse or leave.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "switching",
        "what": "Fortune Transportation pulled its inward-facing cameras after driver feedback, and a driver posted in June 2024 that they quit trucking because every job had these cameras.",
        "cites": ["src:4", "src:2"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Company announces dual-facing cameras for insurance reasons", "cites": ["src:1"] },
        { "event": "Drivers learn there is a scoring system nobody mentioned", "cites": ["src:1"] }
      ],
      "who_feels": ["economic_buyer", "champion", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_refusing", "verbatim": "We decided to remove the inward-facing cameras", "cites": ["src:4"] }
          ],
          "costs_them": "Drivers lost to competitors in a market with 44.2% turnover.",
          "fears": "Paying for safety tech and losing the drivers it was meant to protect.",
          "dream_outcome": "Drivers see the camera as a witness on their side, not a boss."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "It wasn't necessarily the most popular thing among the fleet, so we had to obviously sell it to the drivers.", "cites": ["src:4"] }
          ],
          "costs_them": "Weeks of selling the rollout one driver at a time.",
          "fears": "A rollout that tanks morale and gets reversed.",
          "dream_outcome": "Drivers stop bringing it up."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Don’t believe a thing they tell you. They record 24/7. Video and audio.", "cites": ["src:1"] },
            { "situation": "venting", "verbatim": "The only thing that matters is playing the stupid Samsara game and hoping you get a good safety manager", "cites": ["src:2"] }
          ],
          "costs_them": "Privacy in the cab they live in, and their job if the score turns.",
          "fears": "A bad manager using the footage against them.",
          "dream_outcome": "The camera proves them right in a crash and leaves them alone otherwise."
        }
      },
      "relief": {
        "line": "The grumbling fades. Drivers stop fighting the camera once it has saved one of them.",
        "says": [
          { "role": "economic_buyer", "verbatim": "Over time, it's gotten better. We don't hear as much about it.", "cites": ["src:4"] }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Cameras become a reason to stay. Drivers pick the fleet that has their back on video.",
        "says": [],
        "gap": "Looked in TruckersReport threads and trade press for a driver choosing a carrier because of its cameras; found none quoted directly."
      },
      "segments": ["seg:trucking", "seg:public"],
      "feature_ref": "feat:workforce",
      "cites": ["src:1", "src:2", "src:3", "src:4", "src:10"]
    },
    {
      "id": "pain:alerts-punish-safe-driving",
      "statement": "The camera writes me up for glancing at my dash or braking hard to avoid a wreck, and it misses the people actually on their phones.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "AI events fire on normal driving and miss real distraction.",
        "operational": "Bad events poison the safety score, waste coaching time, and teach drivers to game the system.",
        "personal": "Drivers get yelled at and written up for things they didn't do wrong, which feels like being treated as a suspect."
      },
      "workflow": "An in-cab alert fires, the event lands in the safety manager's queue, and the driver gets a coaching session or a write-up based on a clip that may be wrong.",
      "type": "felt",
      "confidence": "high",
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "On Trustpilot in October 2026 a driver wrote they were written up for two cell phone violations; in July 2026 a fleet buyer wrote the AI misses phone use and drivers learn to cheat it; a June 2026 forum post says hard braking to avoid a crash is safe driving, not a violation.",
        "cites": ["src:7", "src:2"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Driver gets written up for a flagged event they dispute", "cites": ["src:7"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "I Just got yelled at and wrote up for two cell phone violations", "cites": ["src:7"] },
            { "situation": "venting", "verbatim": "Looking down at your dashboard is normal, and hitting the brakes hard to avoid an accident is safe driving, not a violation.", "cites": ["src:2"] }
          ],
          "costs_them": "Write-ups on their record and constant nagging in the cab.",
          "fears": "Getting fired over a false event.",
          "dream_outcome": "Only real mistakes get flagged."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "AI does not recognise mobile usage and my drivers learn to cheat it.", "cites": ["src:7"] }
          ],
          "costs_them": "Coaching time spent on wrong events while real risk slips through.",
          "fears": "Drivers stop trusting every event, so coaching stops working.",
          "dream_outcome": "Events accurate enough that drivers accept the coaching."
        }
      },
      "relief": {
        "line": "Events you can trust. A flagged clip is a real mistake, so the coaching talk is short and fair.",
        "says": [],
        "gap": "No driver or safety manager in Trustpilot or TruckersReport described accurate alerts in their own words."
      },
      "euphoria": {
        "line": "The score means something. Drivers treat a good safety score as earned.",
        "says": [],
        "gap": "Not found in the sources read."
      },
      "segments": ["seg:trucking"],
      "feature_ref": "feat:cameras",
      "cites": ["src:2", "src:7"]
    },
    {
      "id": "pain:event-review-grind",
      "statement": "Somebody has to watch every camera event and coach every flagged driver, and that somebody is a full-time hire.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "A daily queue of camera and HOS events to review.",
        "operational": "Fleets add safety and compliance headcount just to keep up with event review, coaching and CSA scores.",
        "personal": "The safety person spends the day in the queue instead of preventing the next crash."
      },
      "workflow": "Each morning the safety specialist opens the camera and ELD dashboards, reviews inward and outward events, schedules coaching talks on HOS violations, and tracks CSA scores.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "hiring",
        "what": "NOW Courier posted a DOT Safety and Compliance Specialist role on 2026-08-27 whose duties are reviewing camera events and coaching drivers.",
        "cites": ["src:9"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Camera rollout creates more events than current staff can review", "cites": ["src:9"] }
      ],
      "who_feels": ["champion"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Conduct coaching discussions with drivers regarding HOS violations and corrective actions.", "cites": ["src:9"] }
          ],
          "costs_them": "A salary line for review work.",
          "fears": "Missing the one event that mattered in a pile of noise.",
          "dream_outcome": "Only the events worth a conversation reach them."
        }
      },
      "relief": {
        "line": "A short queue. Only events that need a human reach the safety desk.",
        "says": [],
        "gap": "Job postings describe the work, not the relief; no safety manager quote found."
      },
      "euphoria": {
        "line": "Safety runs without a new hire. Coaching keeps up as the fleet grows.",
        "says": [],
        "gap": "Not found in the sources read."
      },
      "segments": ["seg:trucking"],
      "feature_ref": "feat:platform",
      "cites": ["src:9"]
    },
    {
      "id": "pain:no-buses-no-answers",
      "statement": "We have open routes we can't staff, and parents have no idea when, or if, the bus is coming.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Bus driver shortage leaves routes open and buses late.",
        "operational": "The district can't tell families where buses are, so delays turn into calls and complaints.",
        "personal": "The transportation director starts the school year announcing delays in public."
      },
      "workflow": "At the start of the school year the transportation office posts open routes, warns families of delays, and rolls out a parent bus tracking app.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "paying",
        "what": "Prince George's County Public Schools opened 2025-26 with open routes and rolled out a real-time bus tracking app for parents.",
        "cites": ["src:13"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Start of a school year with unfilled routes", "cites": ["src:13"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "resulting in open routes and anticipated transportation delays", "cites": ["src:13"] }
          ],
          "costs_them": "Late buses, open routes and a flood of parent complaints.",
          "fears": "Public blame for kids stranded at stops.",
          "dream_outcome": "Parents see the bus live and stop calling."
        }
      },
      "relief": {
        "line": "Parents can see the bus. Real-time tracking and arrival alerts replace the phone calls.",
        "says": [],
        "gap": "Only the district's press release, not a director or parent in their own words, describes the tracking."
      },
      "euphoria": {
        "line": "Transportation stops being the story. The district runs fewer drivers on smarter routes without public fallout.",
        "says": [],
        "gap": "Not found in the sources read."
      },
      "segments": ["seg:public"],
      "feature_ref": "feat:telematics",
      "cites": ["src:13"]
    },
    {
      "id": "pain:data-noise",
      "statement": "The system throws so much data at me that I can't find the three things I actually need today.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Dashboards full of reports nobody reads.",
        "operational": "Real problems get buried and the platform gets used for a fraction of what it costs.",
        "personal": null,
        "personal_note": "No source shows what the noise costs the manager personally beyond wasted time."
      },
      "workflow": "The fleet manager logs into the telematics dashboard and has to dig through reports and alerts to find what needs action that day.",
      "type": "latent",
      "confidence": "low",
      "priority": 6,
      "felt_evidence": null,
      "revealed_by": "feat:platform",
      "triggers": [
        { "event": "Platform rollout adds more reports than the team can read", "cites": ["src:12", "src:6"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "There’s too much data available, and a lot of it is irrelevant to day-to-day operations.", "cites": ["src:12"] },
            { "situation": "when_it_bites", "verbatim": "Powerful tool, which we don’t yet fully utilise but we will", "cites": ["src:6"] }
          ],
          "costs_them": "Paying for a platform they only partly use.",
          "fears": "Missing a real problem buried in the noise.",
          "dream_outcome": "Open it once a day and see only what needs action."
        }
      },
      "relief": {
        "line": "Only what matters. The dashboard surfaces the exceptions and hides the rest.",
        "says": [],
        "gap": "The one fleet manager quote is in a vendor blog; no buyer described the relief."
      },
      "euphoria": {
        "line": "The data runs the fleet. Decisions come from the platform without anyone digging.",
        "says": [],
        "gap": "Not found in the sources read."
      },
      "segments": ["seg:trucking", "seg:construction", "seg:public"],
      "feature_ref": "feat:platform",
      "cites": ["src:6", "src:12"]
    },
    {
      "id": "pain:locked-in-then-abandoned",
      "statement": "They sell you a multi-year contract, then support disappears and you can't get a broken gateway replaced.",
      "element": "b2b:ease_of_doing_business:commitment",
      "shape": {
        "surface": "Slow support, repeated troubleshooting, hardware not replaced.",
        "operational": "Trucks run with dead units and missing logs while the fleet stays locked into the term.",
        "personal": "The buyer who signed the deal looks bad when the system they picked stops working."
      },
      "workflow": "When a gateway or camera fails the fleet admin opens a ticket, repeats the same troubleshooting steps, and chases a replacement while the vehicle reports nothing.",
      "type": "felt",
      "confidence": "medium",
      "priority": 7,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Trustpilot reviews from July to September 2026 describe poor support, unreplaced gateways and repeated troubleshooting loops; ComplaintsBoard posts dispute cancellation terms.",
        "cites": ["src:6", "src:7", "src:8"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Gateways fail and replacements stall", "cites": ["src:7"] },
        { "event": "Trying to cancel or downsize mid-contract", "cites": ["src:8"] }
      ],
      "who_feels": ["economic_buyer", "technical_evaluator"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "A proper disaster: they are interested in selling you their product; you will be on your own after that.", "cites": ["src:6"] },
            { "situation": "when_refusing", "verbatim": "Nowhere in my contract does it mention any cancellation fee or amount, only the requirement to return the device.", "cites": ["src:8"] }
          ],
          "costs_them": "Paying for units that don't report, and fees to get out.",
          "fears": "Being stuck for years with a vendor that stopped answering.",
          "dream_outcome": "A vendor that fixes things fast and earns the renewal."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "venting", "verbatim": "We are repeatedly asked to follow the same troubleshooting steps", "cites": ["src:7"] }
          ],
          "costs_them": "Hours on support loops.",
          "fears": "Vehicles going dark during an audit or a crash.",
          "dream_outcome": "Broken hardware swapped without a fight."
        }
      },
      "relief": {
        "line": "Fixed the first time. Support solves it in one call.",
        "says": [
          { "role": "technical_evaluator", "verbatim": "Fast response, figured the problem out in a timely matter!", "cites": ["src:7"] }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "A partner, not a vendor. The fleet renews because it wants to.",
        "says": [],
        "gap": "Positive Trustpilot reviews from a July 2026 customer event read as solicited, so not used."
      },
      "segments": ["seg:trucking", "seg:construction"],
      "feature_ref": null,
      "feature_note": "Commercial terms and support quality, not a product feature; killed by flexible contracts and fast hardware replacement.",
      "cites": ["src:6", "src:7", "src:8"]
    },
    {
      "id": "pain:racing-the-clock",
      "statement": "Since the ELD I'm racing the clock all day, driving tired because I can't stop to nap without losing my hours.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "The 14-hour clock keeps running through dock waits and naps.",
        "operational": "Drivers speed or skip rest to finish inside legal hours, which raises crash risk.",
        "personal": "Drivers are exhausted and lose pay sitting at docks."
      },
      "workflow": "The driver logs on-duty in the ELD driver app, waits at a shipper dock while the 14-hour clock runs, then drives hard to reach parking before hours run out.",
      "type": "felt",
      "confidence": "medium",
      "priority": 8,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Drivers told FleetOwner they drive faster and take more chances to beat the clock; this source is from 2018 and no fresher driver complaint was fetched.",
        "cites": ["src:11"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "Long detention at a shipper dock", "cites": ["src:11"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Since I was forced onto an ELD I am so tired, get no rest, and am racing the clock all day to get to a place to park", "cites": ["src:11"] },
            { "situation": "when_it_bites", "verbatim": "I've been driving much faster and taking more chances lately just to beat the clock", "cites": ["src:11"] }
          ],
          "costs_them": "Sleep, pay lost at docks, and safety margin.",
          "fears": "Running out of hours with nowhere legal to park.",
          "dream_outcome": "Rest when tired and get paid for waiting."
        }
      },
      "relief": {
        "line": "Hours that fit the day. The driver can plan rest and parking before the clock runs out.",
        "says": [],
        "gap": "No driver described relief from an ELD in the sources read."
      },
      "euphoria": {
        "line": "Not found.",
        "says": [],
        "gap": "Relief here depends on HOS rules, not software; no source shows it."
      },
      "segments": ["seg:trucking"],
      "feature_ref": "feat:workforce",
      "cites": ["src:11"]
    },
    {
      "id": "pain:idle-and-missing-equipment",
      "statement": "Machines sit idle on one job while we rent the same thing for another, because nobody knows where ours got parked.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "Equipment idle, misplaced or stolen.",
        "operational": "Contractors over-rent and over-buy because they can't see what they already own.",
        "personal": null,
        "personal_note": "Only a vendor source was read; no equipment manager described the personal cost."
      },
      "workflow": "The equipment manager calls site supervisors or walks yards to find a machine before approving a rental for the next job.",
      "type": "latent",
      "confidence": "low",
      "priority": 9,
      "felt_evidence": null,
      "revealed_by": "feat:equipment",
      "triggers": [
        { "event": "A new job needs equipment the company may already own", "cites": ["src:14"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_looking", "verbatim": "Roughly 30% of construction equipment time is idle, which is a huge sinkhole for cost and efficiency.", "cites": ["src:14"] }
          ],
          "costs_them": "Rental bills for machines they already own.",
          "fears": "Theft discovered weeks late.",
          "dream_outcome": "Every machine on one map with its hours."
        }
      },
      "relief": {
        "line": "Find it in a click. Every machine's location and hours on one screen.",
        "says": [],
        "gap": "Construction trade sites that quote contractors returned 403; only a vendor blog was readable."
      },
      "euphoria": {
        "line": "Buy less iron. Utilization data drives the next purchase.",
        "says": [],
        "gap": "Not found in the sources read."
      },
      "segments": ["seg:construction"],
      "feature_ref": "feat:equipment",
      "cites": ["src:14"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Trucking fleets know AI dash cams and telematics are the fix for liability and safety; job postings name the camera systems and duties, and buyers compare vendors on support and contracts.",
      "cites": ["src:9", "src:4", "src:6"]
    },
    "seg:construction": {
      "level": "problem",
      "rationale": "Idle and missing equipment is named as a cost, but no contractor source read shows them comparing solutions.",
      "cites": ["src:14"]
    },
    "seg:public": {
      "level": "solution",
      "rationale": "Districts know GPS tracking and parent apps answer the late-bus problem and are buying them.",
      "cites": ["src:13"]
    }
  },
  "stats": [
    { "id": "stat:verdicts-over-1m", "stat": "Trucking verdicts over $1 million rose from 26 cases in the first five years of ATRI's data to nearly 300 in the last five; award size grew 51.7% a year.", "scope": "US trucking litigation, 2006-2019, ATRI 600-case database", "cites": ["src:5"] },
    { "id": "stat:driver-turnover", "stat": "Driver turnover was 44.2% in 2025.", "scope": "US truckload carriers, ATRI 2026 operational cost update", "cites": ["src:10"] },
    { "id": "stat:insurance-per-mile", "stat": "Insurance cost rose to 10.6 cents a mile in 2025 from 10.2 cents; total cost hit $2.336 a mile.", "scope": "US trucking, ATRI 2026 update", "cites": ["src:10"] },
    { "id": "stat:equipment-idle", "stat": "Roughly 30% of construction equipment time is idle.", "scope": "Construction equipment, vendor estimate, methodology not given", "cites": ["src:14"] }
  ],
