    "nuclear verdicts",
    "dash cam exoneration",
    "inward facing camera",
    "driver facing camera privacy",
    "safety score",
    "false camera alerts",
    "driver coaching",
    "CSA scores",
    "HOS violations",
    "14-hour clock",
    "driver turnover",
    "insurance premiums trucking",
    "camera event review",
    "Samsara contract cancellation",
    "Samsara support",
    "bus driver shortage",
    "real-time bus tracking",
    "idle equipment",
    "equipment theft"
